// UpdateProfile implements mm_port.AdminApplicationUseCase
func (mmUpdateProfile *AdminApplicationUseCaseMock) UpdateProfile(ctx context.Context, cmd mm_port.UpdateProfileCommand) (err error) {
	mm_atomic.AddUint64(&mmUpdateProfile.beforeUpdateProfileCounter, 1)
	defer mm_atomic.AddUint64(&mmUpdateProfile.afterUpdateProfileCounter, 1)

	mmUpdateProfile.t.Helper()

	if mmUpdateProfile.inspectFuncUpdateProfile != nil {
		mmUpdateProfile.inspectFuncUpdateProfile(ctx, cmd)
	}

	mm_params := AdminApplicationUseCaseMockUpdateProfileParams{ctx, cmd}

	// Record call args
	mmUpdateProfile.UpdateProfileMock.mutex.Lock()
	mmUpdateProfile.UpdateProfileMock.callArgs = append(mmUpdateProfile.UpdateProfileMock.callArgs, &mm_params)
	mmUpdateProfile.UpdateProfileMock.mutex.Unlock()

	for _, e := range mmUpdateProfile.UpdateProfileMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmUpdateProfile.UpdateProfileMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpdateProfile.UpdateProfileMock.defaultExpectation.Counter, 1)
		mm_want := mmUpdateProfile.UpdateProfileMock.defaultExpectation.params
		mm_want_ptrs := mmUpdateProfile.UpdateProfileMock.defaultExpectation.paramPtrs

		mm_got := AdminApplicationUseCaseMockUpdateProfileParams{ctx, cmd}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpdateProfile.t.Errorf("AdminApplicationUseCaseMock.UpdateProfile got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateProfile.UpdateProfileMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.cmd != nil && !minimock.Equal(*mm_want_ptrs.cmd, mm_got.cmd) {
				mmUpdateProfile.t.Errorf("AdminApplicationUseCaseMock.UpdateProfile got unexpected parameter cmd, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateProfile.UpdateProfileMock.defaultExpectation.expectationOrigins.originCmd, *mm_want_ptrs.cmd, mm_got.cmd, minimock.Diff(*mm_want_ptrs.cmd, mm_got.cmd))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpdateProfile.t.Errorf("AdminApplicationUseCaseMock.UpdateProfile got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpdateProfile.UpdateProfileMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpdateProfile.UpdateProfileMock.defaultExpectation.results
		if mm_results == nil {
			mmUpdateProfile.t.Fatal("No results are set for the AdminApplicationUseCaseMock.UpdateProfile")
		}
		return (*mm_results).err
	}
	if mmUpdateProfile.funcUpdateProfile != nil {
		return mmUpdateProfile.funcUpdateProfile(ctx, cmd)
	}
	mmUpdateProfile.t.Fatalf("Unexpected call to AdminApplicationUseCaseMock.UpdateProfile. %v %v", ctx, cmd)
	return
}

