// MinimockUpdateProfileInspect logs each unmet expectation
func (m *AdminApplicationUseCaseMock) MinimockUpdateProfileInspect() {
	for _, e := range m.UpdateProfileMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to AdminApplicationUseCaseMock.UpdateProfile at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateProfileCounter := mm_atomic.LoadUint64(&m.afterUpdateProfileCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateProfileMock.defaultExpectation != nil && afterUpdateProfileCounter < 1 {
		if m.UpdateProfileMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to AdminApplicationUseCaseMock.UpdateProfile at\n%s", m.UpdateProfileMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to AdminApplicationUseCaseMock.UpdateProfile at\n%s with params: %#v", m.UpdateProfileMock.defaultExpectation.expectationOrigins.origin, *m.UpdateProfileMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdateProfile != nil && afterUpdateProfileCounter < 1 {
		m.t.Errorf("Expected call to AdminApplicationUseCaseMock.UpdateProfile at\n%s", m.funcUpdateProfileOrigin)
	}

	if !m.UpdateProfileMock.invocationsDone() && afterUpdateProfileCounter > 0 {
		m.t.Errorf("Expected %d calls to AdminApplicationUseCaseMock.UpdateProfile at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateProfileMock.expectedInvocations), m.UpdateProfileMock.expectedInvocationsOrigin, afterUpdateProfileCounter)
	}
}

